    q = String(q || '').trim().toLowerCase(); if (!q) return []; const ws = q.split(/\s+/);
    return all().map(a => { const t = a.title.toLowerCase(), sh = a.short.toLowerCase(), tg = (a.tags || '').toLowerCase(), b = a._p || (a._p = plain(a.body)); let sc = 0;
      for (const w of ws) { let s = 0; if (t === w) s = 100; else if (t.startsWith(w)) s = 60; else if (t.includes(w)) s = 40; else if (tg.includes(w) || a.id.includes(w)) s = 25; else if (sh.includes(w)) s = 15; else if (b.includes(w)) s = 5; if (!s) return null; sc += s; } return { a, sc }; })
      .filter(Boolean).sort((x, y) => y.sc - x.sc || x.a.title.localeCompare(y.a.title, 'de')).map(x => x.a);
